# 40_figures.R: two alternative layouts of the redesigned Figure 6 (plotting only; reads revision_fig6/tables). Run from final/.
# Version A (ecological interpretation): A conditional predictions across TP positions at matched spread (spread-only vs additive); B changes in occupancy-associated dissimilarity, abundance heterogeneity and total dissimilarity as TP spread increases at each position;
# C compensation between components (absolute pp). Version B (GDM-style): A directional I-spline transformations (independent marginal fits); B explicit TP position contributions on the link scale (independent marginal fits, additive model); C coherent predicted responses for the matched contrasts.
# Independent y scales per order; absolute spline slopes are not compared between orders. Descriptive predictions, not causal effects.
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(tidyr); library(patchwork); library(scales)}); stopifnot(requireNamespace("svglite", quietly = TRUE)); IN <- "revision_fig6/tables"; OUTF <- "revision_fig6/figures"
ink <- "#252B2D"; petrol <- "#246878"; orange <- "#C45C19"; sage <- "#79936C"; purple <- "#615A83"; grey <- "#848B8D"; grid_col <- "#E5E9E9"
COMPCOL <- c(Occupancy = petrol, Heterogeneity = orange, Total = purple); MODCOL <- c("Additive MS-GDUM" = ink, "Spread-only MS-GDM" = grey); POSLAB <- c(Low = "Low\n10", Intermediate = "Intermediate\n35", High = "High\n100")
PAN <- function(g, k) paste0(c(BM = "Macroinvertebrates", ZP = "Zooplankton")[g], "\nk = ", k); ORDERP <- c("Macroinvertebrates\nk = 2", "Macroinvertebrates\nk = 5", "Zooplankton\nk = 2", "Zooplankton\nk = 4")
base <- theme_minimal(base_size = 8.5, base_family = "sans") + theme(text = element_text(colour = ink), axis.text = element_text(size = 6.6, colour = ink), axis.title = element_text(size = 7.4, colour = ink), axis.line = element_line(colour = ink, linewidth = .3), axis.ticks = element_line(colour = ink, linewidth = .25), axis.ticks.length = unit(1, "mm"), panel.grid.major = element_line(colour = grid_col, linewidth = .25), panel.grid.minor = element_blank(), panel.spacing = unit(2.2, "mm"),
  strip.background = element_blank(), strip.text = element_text(size = 6.8, face = "bold", colour = ink), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 6.6), legend.key.height = unit(2.4, "mm"), legend.key.width = unit(5, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(1, "mm"), plot.tag = element_text(size = 11, face = "bold"), plot.margin = margin(2, 3, 1, 2))
mlab <- function(m) factor(c(additive = "Additive MS-GDUM", spread_only = "Spread-only MS-GDM")[m], names(MODCOL)); plab <- function(d) mutate(d, panel = factor(PAN(group, order), ORDERP), position = factor(position, names(POSLAB), unname(POSLAB)))
SUP <- read.csv(file.path(IN, "fig6_support_summary.csv")); PR <- read.csv(file.path(IN, "fig6_predictions_grid.csv")); CA <- read.csv(file.path(IN, "fig6_contrast_A_spread.csv")); CB <- read.csv(file.path(IN, "fig6_contrast_B_with_compensation.csv")); MG <- read.csv(file.path(IN, "fig6_independent_spread_curves.csv")); PC <- read.csv(file.path(IN, "fig6_independent_position_contributions.csv"))
make <- function(pool) { sup <- SUP |> filter(pool == !!pool) |> mutate(panel = factor(PAN(group, order), ORDERP)); note <- sup |> transmute(panel, label = ifelse(matched_available, sprintf("%d supported configurations; spread %.2f-%.2f", n_supported_reference_configurations, spread_from, spread_to), "no common environmental support"))
  pr <- PR |> filter(pool == !!pool) |> plab() |> mutate(model = mlab(model)); ca <- CA |> filter(pool == !!pool) |> plab() |> mutate(model = mlab(model)); cb <- CB |> filter(pool == !!pool) |> mutate(panel = factor(PAN(group, order), ORDERP), model = mlab(model)); allp <- levels(pr$panel)
  # ---------------- Version A ----------------
  spr <- pr |> group_by(panel, group, order) |> mutate(s_lo = min(spread), s_hi = max(spread)) |> filter(spread %in% c(s_lo, s_hi)) |> mutate(sl = factor(ifelse(spread == s_lo, "Low spread", "High spread"), c("Low spread", "High spread"))) |> ungroup()
  A1 <- ggplot(spr, aes(position, total, colour = model, linetype = sl, group = interaction(model, sl))) + geom_line(linewidth = .65) + geom_point(aes(shape = model), size = 1.5, fill = "white") + facet_wrap(~panel, nrow = 1, scales = "free_y", drop = FALSE) + scale_colour_manual(values = MODCOL) + scale_shape_manual(values = c("Additive MS-GDUM" = 16, "Spread-only MS-GDM" = 21)) + scale_linetype_manual(values = c("Low spread" = "dashed", "High spread" = "solid")) + labs(tag = "A", x = NULL, y = "Predicted total\ndissimilarity") + base + theme(axis.text.x = element_blank())
  cd <- ca |> select(panel, position, model, `Occupancy-associated` = dO_pp, `Abundance heterogeneity` = dH_pp, `Total` = dT_pp) |> pivot_longer(-c(panel, position, model), names_to = "component", values_to = "pp") |> mutate(component = factor(component, c("Occupancy-associated", "Abundance heterogeneity", "Total")))
  ccol <- c("Occupancy-associated" = petrol, "Abundance heterogeneity" = orange, "Total" = purple)
  B1 <- ggplot(cd |> filter(model == "Additive MS-GDUM"), aes(position, pp, fill = component)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .3) + geom_col(position = position_dodge(.8), width = .7) + geom_point(data = cd |> filter(model == "Spread-only MS-GDM"), aes(colour = component), shape = 21, fill = "white", stroke = .7, size = 1.5, position = position_dodge(.8)) + facet_wrap(~panel, nrow = 1, scales = "free_y", drop = FALSE) + scale_fill_manual(values = ccol) + scale_colour_manual(values = ccol, guide = "none") + labs(tag = "B", x = NULL, y = "Change with increasing\nTP spread (pp)") + base + theme(axis.text.x = element_blank(), strip.text = element_blank())
  cc <- ca |> transmute(panel, position, model, `Gross change |dO| + |dH|` = gross_pp, `Net change |dT|` = net_total_pp, `Compensated (gross - net)/2` = compensated_pp) |> pivot_longer(-c(panel, position, model), names_to = "measure", values_to = "pp") |> mutate(measure = factor(measure, c("Gross change |dO| + |dH|", "Net change |dT|", "Compensated (gross - net)/2")))
  frac <- ca |> filter(model == "Additive MS-GDUM") |> transmute(panel, position, label = ifelse(is.finite(fraction_compensated), sprintf("%.0f%%", 100 * fraction_compensated), ""), y = gross_pp)
  C1 <- ggplot(cc |> filter(model == "Additive MS-GDUM"), aes(position, pp, fill = measure)) + geom_col(position = position_dodge(.8), width = .7) + geom_point(data = cc |> filter(model == "Spread-only MS-GDM"), aes(colour = measure), shape = 21, fill = "white", stroke = .7, size = 1.5, position = position_dodge(.8)) + geom_text(data = frac, aes(position, y, label = label), inherit.aes = FALSE, vjust = -.6, size = 2, colour = grey) + facet_wrap(~panel, nrow = 1, scales = "free_y", drop = FALSE) + scale_fill_manual(values = c(sage, purple, orange)) + scale_colour_manual(values = c(sage, purple, orange), guide = "none") + scale_y_continuous(expand = expansion(mult = c(.02, .15))) + labs(tag = "C", x = "TP position (ug/L)", y = "Absolute change (pp)") + base + theme(strip.text = element_blank())
  nt <- ggplot(note, aes(1, 1, label = label)) + geom_text(size = 2.1, colour = grey) + facet_wrap(~panel, nrow = 1, drop = FALSE) + theme_void() + theme(strip.text = element_blank(), plot.margin = margin(0, 3, 0, 2))
  figA <- (A1 / B1 / C1 / nt) + plot_layout(heights = c(1, 1.05, 1.1, .1))
  # ---------------- Version B ----------------
  mg <- MG |> filter(pool == !!pool, component %in% c("occupancy", "total", "heterogeneity")) |> mutate(panel = factor(PAN(group, order), ORDERP), model = mlab(model), component = factor(c(occupancy = "Occupancy-associated", heterogeneity = "Abundance heterogeneity", total = "Total")[component], c("Occupancy-associated", "Abundance heterogeneity", "Total")))
  VA <- ggplot(mg, aes(TP_ugL, f_centred, colour = model, linetype = model)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .25) + geom_line(linewidth = .65) + ggh4x::facet_grid2(component ~ panel, scales = "free_y", independent = "y", drop = FALSE) + scale_x_log10(breaks = c(3, 10, 30, 100, 300), labels = c(3, 10, 30, 100, 300)) + scale_colour_manual(values = MODCOL) + scale_linetype_manual(values = c("Additive MS-GDUM" = "solid", "Spread-only MS-GDM" = "dashed")) + labs(tag = "A", x = NULL, y = "Directional TP transformation\n(link scale, centred; independent marginal fits)") + base + theme(strip.text.y = element_text(size = 5.8, angle = 0), axis.text.x = element_blank())
  pcn <- PC |> filter(pool == !!pool, component %in% c("occupancy", "total", "heterogeneity")) |> mutate(panel = factor(PAN(group, order), ORDERP), component = factor(c(occupancy = "Occupancy-associated", heterogeneity = "Abundance heterogeneity", total = "Total")[component], c("Occupancy-associated", "Abundance heterogeneity", "Total")))
  VB <- ggplot(pcn, aes(TP_ugL, g_centred, colour = component)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .25) + geom_line(linewidth = .7) + facet_wrap(~panel, nrow = 1, scales = "free_y", drop = FALSE) + scale_x_log10(breaks = c(3, 10, 30, 100, 300), labels = c(3, 10, 30, 100, 300)) + scale_colour_manual(values = ccol) + labs(tag = "B", x = "Site TP (ug/L, log axis)", y = "Explicit position contribution\n(link scale; additive model, independent fits)") + base + theme(strip.text = element_blank())
  ca2 <- ca |> select(panel, position, model, `Occupancy-associated` = dO_pp, `Abundance heterogeneity` = dH_pp, Total = dT_pp) |> pivot_longer(-c(panel, position, model), names_to = "component", values_to = "pp") |> mutate(component = factor(component, c("Occupancy-associated", "Abundance heterogeneity", "Total")), contrast = "TP spread increases (matched interval)")
  cb2 <- cb |> filter(position_from == "Low", position_to == "High") |> group_by(panel, model) |> filter(spread == median(unique(spread)) | spread == spread[ceiling(n() / 2)]) |> slice(1) |> ungroup() |> transmute(panel, position = factor("Low->High", c("Low->High")), model, `Occupancy-associated` = dO_pp, `Abundance heterogeneity` = dH_pp, Total = dT_pp) |> pivot_longer(-c(panel, position, model), names_to = "component", values_to = "pp") |> mutate(component = factor(component, c("Occupancy-associated", "Abundance heterogeneity", "Total")), contrast = "TP position increases (mid spread)")
  cc2 <- bind_rows(ca2 |> mutate(position = as.character(position)), cb2 |> mutate(position = as.character(position))) |> mutate(xlab = factor(ifelse(contrast == "TP position increases (mid spread)", "Low-High\nposition", ifelse(grepl("^Inter", position), "Int.", gsub("\n.*", "", position))), c("Low", "Int.", "High", "Low-High\nposition")))
  VC <- ggplot(cc2 |> filter(model == "Additive MS-GDUM"), aes(xlab, pp, fill = component)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .3) + geom_col(position = position_dodge(.8), width = .7) + geom_point(data = cc2 |> filter(model == "Spread-only MS-GDM"), aes(colour = component), shape = 21, fill = "white", stroke = .7, size = 1.4, position = position_dodge(.8)) + facet_wrap(~panel, nrow = 1, scales = "free_y", drop = FALSE) + scale_fill_manual(values = ccol) + scale_colour_manual(values = ccol, guide = "none") + labs(tag = "C", x = "Spread contrast at each TP position | position contrast", y = "Coherent predicted\nchange (pp)") + base + theme(strip.text = element_blank(), axis.text.x = element_text(size = 5.6))
  figB <- (VA / VB / VC / nt) + plot_layout(heights = c(2.2, .8, 1.1, .1))
  list(A = figA, B = figB) }
ex <- function(g, stem, h) for (e in c("pdf", "svg", "png")) ggsave(file.path(OUTF, paste0(stem, ".", e)), g, width = 183, height = h, units = "mm", dpi = 600, bg = "white", device = switch(e, pdf = grDevices::cairo_pdf, svg = svglite::svglite, png = "png"))
for (pool in c("shared", "full")) { f <- make(pool); sfx <- if (pool == "shared") "" else "_full_pool"; ex(f$A, paste0("Figure6_versionA_ecological", sfx), 205); ex(f$B, paste0("Figure6_versionB_GDM_style", sfx), 215) }
# supplement: decomposition of the position contrast
cb <- CB |> filter(pool == "shared", position_from == "Low", position_to == "High") |> mutate(panel = factor(PAN(group, order), ORDERP), model = mlab(model)) |> group_by(panel, model) |> filter(spread == spread[ceiling(n() / 2)]) |> ungroup()
dec <- cb |> select(panel, model, Occupancy = dO_pp, Heterogeneity = dH_pp, Total = dT_pp, spline_slope_dO, explicit_position_dO, spline_slope_dH, explicit_position_dH, spline_slope_dT, explicit_position_dT) |> pivot_longer(c(spline_slope_dO, explicit_position_dO, spline_slope_dH, explicit_position_dH, spline_slope_dT, explicit_position_dT), names_to = "k", values_to = "pp") |> mutate(component = factor(c(O = "Occupancy-associated", H = "Abundance heterogeneity", T = "Total")[sub(".*_d", "", k)], c("Occupancy-associated", "Abundance heterogeneity", "Total")), source = factor(ifelse(grepl("^spline", k), "Spline-slope terms (also in spread-only)", "Explicit position terms"), c("Spline-slope terms (also in spread-only)", "Explicit position terms")))
pS <- ggplot(dec, aes(component, pp, fill = source)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .3) + geom_col(position = position_dodge(.8), width = .7) + facet_grid(model ~ panel, scales = "free_y") + scale_fill_manual(values = c(grey, orange)) + labs(x = NULL, y = "Contribution to the Low -> High position contrast (pp, Shapley decomposition)") + base + theme(axis.text.x = element_text(angle = 30, hjust = 1, size = 6), strip.text.y = element_text(size = 5.8, angle = 0))
ex(pS, "FigureS6_position_decomposition", 120)
